  const budgetView=budgetPreview(budgetPolicy,cities,channels,budgets);
  const [searchMode,setSearchMode]=useState(saved?.search_mode||'auto');
  const [allowed,setAllowed]=useState(saved?.allowed_providers||(saved?.search_mode&&saved.search_mode!=='auto'?[saved.search_mode]:['model','browser']));
  const changeMode=mode=>{setSearchMode(mode);setAllowed(mode==='auto'?['model','browser']:[mode])};
  const eduSummary=edu?'我的学历：'+boot.candidate_education_options[edu]+'；自动判断我是否满足岗位最低学历要求':'我的学历：未设置；不以学历筛选岗位';
  const [onsite,setOnsite]=useState(saved?.onsite_search??true);
