  const payload=()=>({cities,role,search_mode:searchMode,onsite_search:onsite,candidate_education:edu||null,rules_version:boot.rules_version,allowed_providers:allowed,notes,terms,adjacent_terms:adjacent,channels,budget_policy:budgetPolicy,city_budgets:budgets,channel_budgets:budgetPolicy===PRIORITY_BUDGET?{}:channelBudgets,...limits,experience_years:experience===''?null:Number(experience),salary_amount:salary===''?null:Number(salary),salary_basis:'gross',recruitment_type:type||null});
  const addCity=()=>{const items=cityInput.split(/[,，、\s]+/).filter(Boolean);const next=[...new Set([...cities,...items])];setCities(next);setBudgets(b=>Object.fromEntries(next.map(c=>[c,b[c]??10])));setCityInput('')};
  const setTotal=n=>{if(!cities.length)return;const v=Math.max(cities.length,Math.min(5000,Number(n)||cities.length));setBudgets(Object.fromEntries(cities.map((c,i)=>[c,Math.floor(v/cities.length)+(i<v%cities.length?1:0)])))};
  const toggle=(ids)=>setChannels(c=>ids.every(x=>c.includes(x))?c.filter(x=>!ids.includes(x)):[...new Set([...c,...ids])]);
  const sourceGroups=[['企业官网',Building2,['official_career'],'企业自己的招聘入口'],['招聘网站',Monitor,['zhaopin','boss','liepin','51job'],'公开索引与岗位原文'],['人才平台',Database,['talent_platform'],'人才网、招聘会'],['人社公告',FileText,['public_hr'],'官方公开招聘信息'],['本地宝',MapPin,['bendibao_web'],'城市招聘资讯'],['微信公众号',Globe2,['wechat'],'文章原文与投递方式'],['高校就业网',GraduationCap,['campus'],'企业公告、校园招聘']];
